93	const REQUEST_HEADERS = {
94	  'Content-Type': 'application/json',
95	  Accept: 'application/json, text/event-stream',
96	  [STORYBOOK_MCP_PROXY_HEADER]: STORYBOOK_MCP_PROXY_HEADER_VALUE,
97	};
98	
99	/**
100	 * Send a minimal MCP `initialize` request carrying {@link MCP_CLIENT_INFO} and return the session
101	 * id the transport assigned, or null when the handshake fails in any way.
102	 *
103	 * Its only purpose is telemetry segmentation, and the flow is MCP Streamable HTTP spec behavior,
104	 * not a tmcp implementation detail: the server assigns a session id during initialization,
105	 * returns it in the `Mcp-Session-Id` response header, and associates the session's clientInfo
106	 * with later requests echoing that header. Any spec-compliant server (e.g. the official MCP SDK
107	 * transports) behaves the same, so addon-mcp can move off tmcp without breaking this client.
108	 * The handshake is strictly best-effort — when it fails (or a future server ignores sessions),
109	 * the actual command request proceeds without a session and keeps working; only the telemetry
110	 * segmentation is lost, and error reporting stays anchored on the real call.
111	 *
112	 * Sessions are deliberately one-shot: each JSON-RPC request gets its own handshake and the session
113	 * is never reused or closed. A CLI invocation makes one request on the happy path (two on error
114	 * paths that fetch the tool list), so against a localhost server the extra round-trip is
115	 * negligible — not worth threading session state through the call sites.
116	 *
117	 * The response body is drained before returning because the transport produces it only after the
118	 * server has processed the initialize message (and stored the clientInfo); returning on headers
119	 * alone would race the follow-up request against that processing.
120	 */
121	async function initializeMcpSession(
122	  target: string,
123	  fetchImpl: typeof fetch
124	): Promise<string | null> {
125	  try {
126	    const response = await fetchImpl(target, {
127	      method: 'POST',
128	      headers: REQUEST_HEADERS,
129	      body: JSON.stringify({
130	        jsonrpc: '2.0',
131	        id: crypto.randomUUID(),
132	        method: 'initialize',
133	        params: {
134	          protocolVersion: MCP_PROTOCOL_VERSION,
135	          capabilities: {},
136	          clientInfo: MCP_CLIENT_INFO,
137	        },
138	      }),
139	      signal: AbortSignal.timeout(INITIALIZE_TIMEOUT_MS),
140	    });
141	    const sessionId = response.headers.get('mcp-session-id');
142	    if (!response.ok || !sessionId) {
143	      return null;
144	    }
145	    await response.text();
146	    return sessionId;
147	  } catch {
148	    return null;
149	  }
150	}
