152	/**
153	 * Send a single JSON-RPC request to the instance's MCP endpoint over HTTP.
154	 *
155	 * This is deliberately NOT a full MCP client: the `initialize` request exists solely to convey
156	 * `clientInfo` for telemetry (see {@link initializeMcpSession}) — there is no protocol-version
157	 * negotiation, capability handling, or session lifecycle beyond this one follow-up request. The
158	 * downstream is always `@storybook/addon-mcp`, whose tmcp HttpTransport serves `tools/*`
159	 * per-request — the same local shortcut `@storybook/mcp-proxy` takes in its proxy-client. If the
160	 * CLI ever needs to talk to arbitrary MCP servers, replace this with a real client instead of
161	 * extending it.
162	 *
163	 * tmcp hardcodes `text/event-stream` for any request with an id, so we accept both content-types
164	 * and parse the SSE envelope when needed.
165	 */
166	async function sendJsonRpcRequest<TResult>(
167	  record: StorybookInstanceRecord,
168	  method: 'tools/call' | 'tools/list',
169	  params: unknown,
170	  resultSchema: v.GenericSchema<unknown, TResult>,
171	  fetchImpl: typeof fetch
172	): Promise<TResult> {
173	  const endpoint = record.mcp.endpoint;
174	  if (!endpoint) {
175	    throw new Error(`The Storybook instance at ${record.cwd} has no server endpoint registered`);
176	  }
177	
178	  const target = new URL(endpoint, record.url).href;
179	
180	  const sessionId = await initializeMcpSession(target, fetchImpl);
181	
182	  const response = await fetchImpl(target, {
183	    method: 'POST',
184	    headers: {
185	      ...REQUEST_HEADERS,
186	      ...(sessionId ? { 'Mcp-Session-Id': sessionId } : {}),
187	    },
188	    body: JSON.stringify({
189	      jsonrpc: '2.0',
190	      id: crypto.randomUUID(),
191	      method,
192	      params,
193	    }),
194	    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
195	  });
196	
197	  if (!response.ok) {
198	    throw new Error(
199	      `The Storybook server at ${target} responded with ${response.status} ${response.statusText}`
