15	/**
16	 * Why an invocation failed before any command executed, for the `ai-command` telemetry event
17	 * (storybookjs/storybook#35131). Extends the instance-resolution intercepts with the two CLI-level
18	 * cases: arguments that never parsed, and command names the server does not provide.
19	 */
20	export type AiCommandInterceptReason = InterceptReason | 'invalid-arguments' | 'unknown-command';
21	
22	/**
23	 * Telemetry-facing classification of a run. `help` marks lookups via `--help` flags, which are not
24	 * command executions and are excluded from the `ai-command` event so they cannot skew command
25	 * success rates. `error` carries failures from the server side (error results, transport
26	 * failures, timeouts) for the standard sanitized error path.
27	 */
28	export type AiCommandOutcome =
29	  | { kind: 'success' }
30	  | { kind: 'help' }
31	  | { kind: 'intercept'; reason: AiCommandInterceptReason }
32	  | { kind: 'error'; error: unknown };
33	
34	export type AiToolRunResult = { exitCode: 0 | 1; output: string; outcome: AiCommandOutcome };
35	
36	/**
37	 * The server executed the command and reported an error result. The message is deliberately
38	 * constant — the result text is arbitrary tool output (often containing project paths), and a
39	 * constant message keeps the telemetry error hash stable and aggregatable. The tool's error text
40	 * travels as `cause` instead, which the standard error path only uploads — path-sanitized — when
41	 * the user opted into crash reports.
42	 */
43	class McpToolResultError extends Error {
44	  constructor(options?: ErrorOptions) {
45	    super('The Storybook MCP server returned an error result', options);
46	    this.name = 'McpToolResultError';
47	  }
48	}
