50	/** Injectable dependencies for tests. */
51	export type AiToolRunDeps = {
52	  registryDir?: string;
53	  fetchImpl?: typeof fetch;
54	};
55	
56	export type AiToolOptions = {
57	  /** Project directory of the target Storybook; defaults to `process.cwd()`. */
58	  cwd?: string;
59	  /** Port of the target Storybook, to address one specific instance when several share the cwd. */
60	  port?: string;
61	  /** Raw JSON object with tool arguments (escape hatch for complex values). */
62	  json?: string;
63	};
64	
65	/**
66	 * Run a single MCP tool against the Storybook running at the target cwd and return its result as
67	 * markdown. Intercept conditions (no running instance, addon missing, ...) return the same
68	 * repair-instruction markdown as `@storybook/mcp-proxy`, with exit code 1.
69	 */
70	export async function runAiTool(
71	  toolName: string,
72	  toolArgTokens: string[],
73	  options: AiToolOptions = {},
74	  deps: AiToolRunDeps = {}
75	): Promise<AiToolRunResult> {
76	  const parsed = parseToolArgs(toolArgTokens, {
77	    cwd: options.cwd,
78	    port: options.port,
79	    json: options.json,
80	  });
81	  if (!parsed.ok) {
82	    return {
83	      exitCode: 1,
84	      output: parsed.error,
85	      outcome: { kind: 'intercept', reason: 'invalid-arguments' },
86	    };
87	  }
88	  if (parsed.help) {
89	    return toolHelp(toolName, parsed.cwd, parsed.port, deps);
90	  }
91	
92	  const resolution = await resolveReadyInstance(parsed.cwd, parsed.port, deps);
93	  if (resolution.kind === 'error') {
94	    return {
95	      exitCode: 1,
96	      output: resolution.output,
97	      outcome: { kind: 'intercept', reason: resolution.reason },
98	    };
99	  }
100	  const { record, matches } = resolution;
101	
102	  try {
103	    const result = await callMcpTool(
104	      record,
105	      { name: toolName, arguments: parsed.args },
106	      deps.fetchImpl
107	    );
108	    if (result.isError) {
109	      // addon-mcp reports unknown tools as an error *result* rather than a JSON-RPC error.
110	      const unknownTool = await describeUnknownTool(record, toolName, deps.fetchImpl);
111	      if (unknownTool) {
112	        return {
113	          exitCode: 1,
114	          output: unknownTool,
115	          outcome: { kind: 'intercept', reason: 'unknown-command' },
116	        };
117	      }
118	    }
119	    const siblings = matches.filter((r) => r !== record);
120	    const toolOutput = formatToolResult(result);
121	    const sections = [
122	      ...(siblings.length > 0 ? [formatMultiInstanceWarning(record, siblings)] : []),
123	      toolOutput,
124	    ];
125	    const output = sections.join('\n\n');
126	    if (result.isError) {
127	      return {
128	        exitCode: 1,
129	        output,
130	        outcome: { kind: 'error', error: new McpToolResultError({ cause: toolOutput }) },
131	      };
132	    }
133	    return { exitCode: 0, output, outcome: { kind: 'success' } };
134	  } catch (error) {
135	    if (error instanceof McpJsonRpcError) {
136	      const unknownTool = await describeUnknownTool(record, toolName, deps.fetchImpl);
137	      if (unknownTool) {
138	        return {
139	          exitCode: 1,
140	          output: unknownTool,
141	          outcome: { kind: 'intercept', reason: 'unknown-command' },
142	        };
143	      }
144	      return { exitCode: 1, output: error.message, outcome: { kind: 'error', error } };
145	    }
146	    return {
147	      exitCode: 1,
148	      output: formatServerUnreachable(record, error),
149	      outcome: { kind: 'error', error },
150	    };
151	  }
152	}
